    #[serde(default)]
    tags: Vec<String>,
}

#[expect(clippy::print_stdout, reason = "stdout is the case sink")]
#[expect(clippy::print_stderr, reason = "stderr is the progress log")]
pub async fn run(datacenter: &str, test_users: bool, fixtures: &Path) -> anyhow::Result<()> {
    let app_env = env::var(ENV_APP_ENV).unwrap_or_default();
    if !matches!(app_env.as_str(), "staging" | "devel") {
        bail!("capture runs only in staging or devel: {ENV_APP_ENV}={app_env:?}");
    }
    let init_deadline = Instant::now() + CLIENT_INIT_RETRY_BUDGET;
    let recorder = Arc::new(Recorder::default());
    let metadata = test_users.then(test_users_metadata);
    let (sources, _) = prod_sources(
        datacenter,
        init_deadline,
        false,
        metadata.as_ref(),
        CacheWarming::Off,
    )
    .await;
    let feature_switches = SwitchFiles::beside(&crate::config::fs_path(), Experiments::none())
        .load(None)
        .context("feature switch files")?;
    let country_lists = Arc::new(CountryLists::starting_at_default());
    country_lists.refresh(&feature_switches);
    let client_switches = ClientSwitches::new(Arc::new(ArcSwap::from_pointee(feature_switches)));
    let post_evaluator = PostEvaluator::new(
        Arc::new(sources.observed(Arc::clone(&recorder))),
        RuleEngine::with_country_lists(Arc::clone(&country_lists)),
        Arc::default(),
    );
    let fixtures = Fixtures::load(fixtures)?;
    let tweetypie = tweetypie::connect(init_deadline, metadata.as_ref()).await;
    let build = resolve_build_sha(
        &current_build_information().git_commit_sha,
        env::var(ENV_IMAGE).ok().as_deref(),
    );

    for line in stdin().lock().lines() {
        let line = line?;
        if line.trim().is_empty() {
            continue;
        }
        let request: CaptureRequest = serde_json::from_str(&line).context("request line")?;
        if let Some(viewer_id) = request.viewer_id
            && !fixtures.users.contains(&viewer_id)
        {
            eprintln!(
                "capture: skipped {}: viewer {viewer_id} is not in fixtures.json",
                request.id
            );
            continue;
        }
        let strange_tweets: Vec<u64> = request
            .tweets
            .iter()
            .map(|tweet| tweet.id)
            .filter(|id| !fixtures.tweets.contains(id))
            .collect();
        if !strange_tweets.is_empty() {
            eprintln!(
                "capture: skipped {}: tweets {strange_tweets:?} are not in fixtures.json",
                request.id
            );
            continue;
        }
        let standalone: Vec<TweetId> = request
            .tweets
            .iter()
            .filter(|tweet| tweet.quote_context.is_none())
            .map(|tweet| TweetId(tweet.id))
            .collect();
        let orphans: Vec<u64> = request
            .tweets
            .iter()
            .filter_map(|tweet| tweet.quote_context)
            .map(|quote| quote.outer_tweet_id)
            .filter(|&outer| !standalone.contains(&TweetId(outer)))
            .collect();
        if !orphans.is_empty() {
            eprintln!(
                "capture: skipped {}: the outers {orphans:?} of its quote entries are not standalone entries",
                request.id
            );
            continue;
        }
        let client = request
            .client
            .context(request.viewer_id, request.country_code.as_deref());
        let vf_request = evaluate_tweets_request(
            &client_switches,
            Some(&client),
            request.viewer_id,
            tweetypie::SAFETY_LEVEL,
            request
                .tweets
                .iter()
                .map(|tweet| PlacedCandidate {
                    candidate: RawCandidate {
                        tweet_id: TweetId(tweet.id),
                        request_author_id: None,
                    },
                    placement: placement(tweet.quote_context),
                })
                .collect(),
        );
        let country_code = vf_request.country_code.clone();
        let client_capability = vf_request.client_capability;
        recorder.take();
        let (vf, tp) = join(
            evaluate(&post_evaluator, vf_request),
            get_tweet_fields(&tweetypie, &client, &standalone),
        )
        .await;
        let tp: HashMap<TweetId, TpResult> = standalone.into_iter().zip(tp).collect();
        let recording = recorder.take();
        let unsuccessful = recording.unsuccessful();
        if !unsuccessful.is_empty() {
            eprintln!(
                "capture: skipped {}: failed or partial answers {unsuccessful:?}",
                request.id
            );
            continue;
        }
        match fixtures.strangers(&recording) {
            Ok(strangers) if strangers.is_empty() => {}
            Ok(strangers) => {
                eprintln!(
                    "capture: skipped {}: {strangers:?} are not in fixtures.json",
                    request.id
                );
                continue;
            }
            Err(e) => {
                eprintln!("capture: skipped {}: {e:#}", request.id);
                continue;
            }
        }
        let tweets: Vec<Expected> = request
            .tweets
            .into_iter()
            .filter_map(|tweet| {
                let tp = match tweet.quote_context {
                    None => tp.get(&TweetId(tweet.id))?.clone(),
                    Some(quote) => tp.get(&TweetId(quote.outer_tweet_id))?.inner_quoted(),
                };
                let vf = vf.iter().find(|vf| {
                    vf.tweet_id == tweet.id && vf.placement == placement(tweet.quote_context)
                })?;
                let failed = <&str>::from(Class::Failed);
                if tp.label.0 == <&str>::from(Class::Missing) {
                    eprintln!(
                        "capture: {}: dropped quote entry {}: its outer's answer has no quotedTweetResult",
                        request.id, tweet.id
                    );
                    return None;
                }
                (vf.label.0 != failed && tp.label.0 != failed).then(|| Expected {
                    tweet_id: tweet.id,
                    quote_context: tweet.quote_context,
                    tags: tweet.tags,
                    tweetypie: tp.label,
                    vf: vf.label.clone(),
                    vf_rule: vf.rule.map(|(_, rule)| rule.to_owned()),
                })
            })
            .collect();
        if tweets.is_empty() {
            eprintln!(
                "capture: skipped {}: no tweet answered on both sides",
                request.id
            );
            continue;
        }
        let case = Case {
            id: request.id,
            tags: request.tags,
            captured_at_unix: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .map_or(0, |since| since.as_secs()),
            build: build.clone(),
            viewer_id: request.viewer_id,
            country_code,
            client: request.client,
            client_capability,
            tweets,
            recording,
        };
        println!(
            "{}",
            serde_json::to_string(&Captured::new(case, country_lists.codes()))?
        );
    }
    Ok(())
}

